import fs from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const projectRoot = fileURLToPath(new URL('../', import.meta.url))
const dist = path.join(projectRoot, 'dist')
const provider = process.argv[2]
await fs.access(path.join(dist, 'index.html'))
if (provider === 'netlify') {
  await fs.writeFile(path.join(dist, '_redirects'), '/* /index.html 200\n')
} else if (provider === 'cloudflare') {
  await fs.rm(path.join(dist, '404.html'), { force: true })
  await fs.rm(path.join(dist, '_redirects'), { force: true })
} else {
  throw new Error('Unsupported provider output: ' + provider)
}

